/**
 * Android 专用的 koffi 占位实现。
 *
 * 背景：koffi 是 Windows 原生的 FFI 绑定，本 payload 内只有源码、没有任何平台的原生
 * 二进制（`build/` 为空），因此 `import "koffi"` 在加载期必然抛错。
 * koffi 只被 Windows Job runner 使用（`runner-launch-*.js`），所以改为：
 *   - 类型声明类 API（pointer/struct/array/...）返回惰性标记对象，满足模块加载期需求；
 *   - 真正会触碰原生库的 API（load/alloc/decode/encode/errno）在**被调用时**抛出明确错误。
 * 这些调用只可能出现在 win32 路径上，Android 不可达；Windows 上若 koffi 可用则不会走到这里。
 */

function unsupported(name) {
	return function unavailable() {
		throw new Error(`koffi 占位：${name} 需要 koffi 原生模块，本平台不可用`);
	};
}

/** 类型描述类调用：加载期只需要一个可传递的对象。 */
function type() {
	return { __koffiStubType: true, toString: () => "[koffi-stub-type]" };
}

const stub = {
	pointer: type,
	struct: type,
	array: type,
	union: type,
	alias: type,
	typedef: type,
	types: type,
	load: unsupported("load"),
	alloc: unsupported("alloc"),
	free: unsupported("free"),
	decode: unsupported("decode"),
	encode: unsupported("encode"),
	errno: unsupported("errno"),
	version: "stub"
};

module.exports = stub;
module.exports.default = stub;
